#include <bits/stdc++.h>
using namespace std;

int main() {
    int m, s, k, i, j;
    cin >> m >> s;

    if ((m > 1 && s < 1) || s > m * 9) {
        cout << -1 << ' ' << -1;
    } else {
        for (i = m - 1, k = s; i >= 0; i--) {
            j = max(0, k - 9 * i);
            if (j == 0 && i == m - 1 && k) j = 1;
            cout << j;
            k -= j;
        }

        cout << ' ';

        for (i = m - 1, k = s; i >= 0; i--) {
            j = min(9, k);
            cout << j;
            k -= j;
        }
    }

    return 0;
}

